import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import cp from 'node:child_process';import {chromium} from 'playwright-core';
const CONTRACT_PATH='pls_v16/BINDING_CONTRACT.json',CONTRACT_SHA='6e8558b4545c1084b3a8342eb2f66611de97dc2e78db46f60919666313164140';
const META_SHA='25d1032044996d2eed8cab3b2c9d6bfbfab91349f0ac6e49ef168c307654b24f',MASK_SHA='8935332736286b4b8238966e7a12ee2049d5fab0816a666061db7cb2c9ee56b0';
const OUT=process.env.PLS_V16_OUT||'wip-pls-v16-vector-build',BATCH=1;
const sha=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex'),hash=b=>crypto.createHash('sha256').update(b).digest('hex'),ok=(c,m)=>{if(!c)throw new Error(m);};
fs.mkdirSync(OUT,{recursive:true});ok(sha(CONTRACT_PATH)===CONTRACT_SHA,'BINDING_CONTRACT_SHA');const C=JSON.parse(fs.readFileSync(CONTRACT_PATH,'utf8'));ok(C.status==='ENGINEERING_INPUT_FROZEN__NOT_QUALIFIED__NOT_DEPLOYABLE','CONTRACT_STATUS');
for(const x of [...C.model.tokenizer_and_config_files,...C.model.delivery.parts,...C.runtime.files]){ok(fs.existsSync(x.path),'SUPPORT_MISSING '+x.path);ok(fs.statSync(x.path).size===Number(x.bytes),'SUPPORT_SIZE '+x.path);ok(sha(x.path)===x.sha256,'SUPPORT_HASH '+x.path);}
const joined=Buffer.concat(C.model.delivery.parts.map(x=>fs.readFileSync(x.path)));ok(joined.length===C.model.delivery.original_model_bytes,'MODEL_BYTES');ok(hash(joined)===C.model.model_sha256,'MODEL_REASSEMBLY_HASH');
cp.execFileSync(process.execPath,['.github/wip-semantic-current-pack-build.cjs'],{stdio:['ignore','pipe','inherit'],maxBuffer:32*1024*1024});
const metaPath='wip-current-semantic-pack/metadata.jsonl',maskPath='wip-current-semantic-pack/jesus_mask.bits';ok(sha(metaPath)===META_SHA,'METADATA_HASH');ok(sha(maskPath)===MASK_SHA,'MASK_HASH');
const rows=fs.readFileSync(metaPath,'utf8').trimEnd().split(/\r?\n/).filter(Boolean).map(JSON.parse);ok(rows.length===C.chunker.expected_passages,'PASSAGE_COUNT');
function quantize(v){let m=0;for(const x of v)m=Math.max(m,Math.abs(x));ok(m>0,'ZERO_EMBEDDING');const scale=127/m,q=new Int8Array(v.length);let ss=0;for(let i=0;i<v.length;i++){const z=Math.max(-127,Math.min(127,Math.round(v[i]*scale)));q[i]=z;ss+=z*z;}return {q,inv:1/Math.sqrt(ss)};}
const server=cp.spawn('python3',['-m','http.server','8765','--bind','127.0.0.1'],{cwd:process.cwd(),stdio:['ignore','ignore','inherit']});let browser=null;
try{
 await new Promise(r=>setTimeout(r,900));const exe=process.env.CHROME_PATH||'/usr/bin/google-chrome';ok(fs.existsSync(exe),'CHROME_MISSING '+exe);
 browser=await chromium.launch({headless:true,executablePath:exe,args:['--no-sandbox','--disable-dev-shm-usage']});const page=await browser.newPage();const browserErrors=[];page.on('pageerror',e=>browserErrors.push(String(e)));page.on('console',m=>{if(m.type()==='error')browserErrors.push(m.text());});
 await page.goto('http://127.0.0.1:8765/tools/ldc_pls_v16_vector_build/browser_embed.html',{waitUntil:'load',timeout:120000});await page.waitForFunction(()=>window.__plsV16Ready===true,null,{timeout:120000});
 async function embed(texts){return await page.evaluate(async xs=>await window.embedBatch(xs),texts);}
 const fixtures=JSON.parse(fs.readFileSync('tools/ldc_v1422_vector_probe/fixtures.json','utf8')),fixtureReport=[];
 for(let i=0;i<fixtures.length;i++){const fixtureVector=(await embed([fixtures[i].text]))[0],z=quantize(fixtureVector),exp=Buffer.from(fixtures[i].vector_b64,'base64');let mismatch=0;for(let j=0;j<z.q.length;j++)if(z.q[j]!==exp.readInt8(j))mismatch++;const invDiff=Math.abs(z.inv-Number(fixtures[i].inverse_norm));fixtureReport.push({passage_id:fixtures[i].passage_id,mismatches:mismatch,inverse_norm_abs_diff:invDiff});}
 fs.writeFileSync(path.join(OUT,'protected_fixture_report.json'),JSON.stringify(fixtureReport,null,2)+'\n');for(const x of fixtureReport)ok(x.mismatches===0&&x.inverse_norm_abs_diff<1e-10,'PROTECTED_VECTOR_FIXTURE '+x.passage_id+' '+JSON.stringify(x));
 const dim=C.model.embedding_dim,vectors=Buffer.alloc(rows.length*dim),norms=Buffer.alloc(rows.length*4);
 for(let start=0;start<rows.length;start+=BATCH){const batch=rows.slice(start,start+BATCH),vs=await embed(batch.map(x=>String(x.text||'')));ok(vs.length===batch.length,'BATCH_RESULT_COUNT');for(let i=0;i<vs.length;i++){ok(vs[i].length===dim,'EMBED_DIM');const z=quantize(vs[i]),row=start+i;for(let j=0;j<dim;j++)vectors.writeInt8(z.q[j],row*dim+j);norms.writeFloatLE(z.inv,row*4);}if(start%100===0)console.log(JSON.stringify({phase:'vectors',completed:Math.min(rows.length,start+BATCH),total:rows.length,batch:BATCH}));}
 ok(browserErrors.length===0,'BROWSER_ERRORS '+JSON.stringify(browserErrors.slice(0,5)));const vecPath=path.join(OUT,'vectors.i8'),normPath=path.join(OUT,'inverse_norms.f32le');fs.writeFileSync(vecPath,vectors);fs.writeFileSync(normPath,norms);
 const report={schema:'ldc-pls-v16-vector-build-v2',status:'ENGINEERING_ONLY__NOT_QUALIFIED__NOT_DEPLOYABLE',binding_contract_sha256:CONTRACT_SHA,pack_id:C.pack_id,metadata:{bytes:fs.statSync(metaPath).size,sha256:sha(metaPath)},jesus_mask:{bytes:fs.statSync(maskPath).size,sha256:sha(maskPath)},model:{id:C.model.model_id,revision:C.model.immutable_revision,sha256:C.model.model_sha256,runtime:'Transformers.js protected browser/WASM',protected_fixture_parity:fixtureReport},vectors:{rows:rows.length,cols:dim,dtype:'int8_row_symmetric',bytes:vectors.length,sha256:sha(vecPath)},inverse_norms:{bytes:norms.length,sha256:sha(normPath)},batch:BATCH,browser_errors:browserErrors,app_runtime_wired:false,deployment_authorized:false};
 fs.writeFileSync(path.join(OUT,'vector_build_report.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));
}finally{if(browser)await browser.close().catch(()=>{});server.kill('SIGTERM');}
